# Account-independent per-upgrade data, derived once from compass_upgrades_list/compass_path_ordering above.
# Compass.__init__ only needs to merge this with the one thing that varies per account: level.
compass_upgrades = []
for _path_name, _upgrade_indexes_list in compass_path_ordering.items():
    for _path_ordering, _upgrade_index in enumerate(_upgrade_indexes_list):
        _upgrade_values = compass_upgrades_list[_upgrade_index]
        _clean_name = _upgrade_values[0].replace('(Tap_for_more_info)', '').replace('製', '').replace('_', ' ').rstrip()
        compass_upgrades.append({
            "Name": _clean_name,
            "Index": _upgrade_index,
            "Cost Base": int(_upgrade_values[1]),
            "Cost Increment": float(_upgrade_values[2]),
            "Dust Index": int(_upgrade_values[3]),
            "Max Level": int(_upgrade_values[4]),
            "Value Per Level": safer_convert(_upgrade_values[5], 0.00 if '.' in _upgrade_values[5] else 0),
            "Shape": 'Square' if int(_upgrade_values[9]) == 0 else 'Circle' if int(_upgrade_values[9]) == 1 else 'UnknownShape',
            "Path Name": _path_name,
            "Path Ordering": _path_ordering if _path_name != 'Abomination' else _path_ordering + 1,
            "Description": _upgrade_values[11].replace('_', ' '),
        })

# Account-independent per-abomination data, derived once from compass_titans above. Compass.__init__ only
# needs to merge this with the one thing that varies per account: defeated status.
compass_abominations = []
for _abom_index, _abom_data in enumerate(compass_titans):
    _map_index = int(_abom_data[2])
    if 50 > _map_index:
        _weakness_index = 0
    elif 100 > _map_index:
        _weakness_index = 3
    elif 150 > _map_index:
        _weakness_index = 2
    elif 200 > _map_index:
        _weakness_index = 1
    else:
        _weakness_index = int(_abom_data[11]) % 4
    compass_abominations.append({
        "Name": _abom_data[0].replace('_', ' '),
        "Map Index": _map_index,
        "Image": f'titan-{_abom_index}',
        "Weakness Index": _weakness_index,
    })

